  /// Loads the listing once, the first time a booking arrives.
  ///
  /// The booking holds a listingId but not the title or the photo, and the
  /// stream can rebuild many times. Guarding on the id keeps this to one read
  /// instead of one per rebuild.
  void _ensureListing(String listingId) {
    if (listingId.isEmpty || _loadedListingId == listingId) return;
    _loadedListingId = listingId;
    _fetchListing(listingId);
  }

  Future<void> _fetchListing(String listingId) async {
    try {
      final StayListing? l = await StayListingService.instance.byId(listingId);
      if (!mounted) return;
      setState(() => _listing = l);
    } catch (_) {
      // Swallowed on purpose. The reference, the dates and the status all come
      // from the booking itself — the listing only supplies the title and the
      // photo. A guest who has just booked should not be shown an error
      // because the decoration failed to load.
    }
  }

  Widget _missingBody() => Center(
        child: Padding(
          padding: const EdgeInsets.all(32),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const Icon(Icons.help_outline,
                  size: 56, color: GoOutsColors.primaryBlue),
              const SizedBox(height: 16),
              Text(
                'We could not load this booking',
                textAlign: TextAlign.center,
                style: GoogleFonts.inter(
                    fontSize: 14,
                    fontWeight: FontWeight.w600,
                    color: GoOutsColors.deepNavy),
              ),
              const SizedBox(height: 8),
              Text(
                'It may still have been made. Please check My bookings.',
                textAlign: TextAlign.center,
                style: GoogleFonts.inter(
                    fontSize: 13.5, color: GoOutsColors.bodyText),
              ),
              const SizedBox(height: 24),
              ElevatedButton(
                onPressed: () => Navigator.of(context)
                    .pushReplacementNamed(StayRoutes.myBookings),
                style: ElevatedButton.styleFrom(
                  backgroundColor: GoOutsColors.primaryBlue,
                  foregroundColor: Colors.white,
                ),
                child: const Text('My bookings'),
              ),
            ],
          ),
        ),
      );

  // ── Header ───────────────────────────────────────────────────────────────

  ({IconData icon, Color tint, String title, String body}) _statusCopy(
      StayBooking b) {
    final String place = _listing?.title ?? 'this property';
    switch (b.status) {
      case BookingStatus.confirmed:
      case BookingStatus.inProgress:
        return (
          icon: Icons.check,
          tint: GoOutsColors.tealSecondary,
          title: 'Booking confirmed',
          body: 'Your stay at $place is confirmed.',
        );
      case BookingStatus.declined:
        return (
          icon: Icons.close,
          tint: GoOutsColors.error,
          title: 'The host could not take this booking',
          body: 'Nothing has been charged. You can search for somewhere '
              'else for the same dates.',
        );
      case BookingStatus.cancelledGuest:
      case BookingStatus.cancelledHost:
        return (
          icon: Icons.event_busy,
          tint: GoOutsColors.error,
          title: 'This booking was cancelled',
          body: 'Nothing has been charged.',
        );
      case BookingStatus.completed:
        return (
          icon: Icons.check,
          tint: GoOutsColors.tealSecondary,
          title: 'Stay completed',
          body: 'We hope you enjoyed $place.',
        );
      case BookingStatus.disputed:
        return (
          icon: Icons.gavel,
          tint: GoOutsColors.warning,
          title: 'This booking is under review',
          body: 'We will be in touch about the claim on this stay.',
        );
      case BookingStatus.pending:
        return (
          icon: Icons.schedule,
          tint: GoOutsColors.primaryBlue,
          title: 'Request sent',
          body: 'Your dates at $place are held while the host replies. '
              'They have 24 hours.',
        );
    }
  }

  Widget _buildStatusHeader(StayBooking b) {
    final copy = _statusCopy(b);
    return Column(
      children: [
        Container(
          width: 80,
          height: 80,
          decoration: BoxDecoration(
            color: copy.tint.withValues(alpha: 0.12),
            shape: BoxShape.circle,
          ),
          child: Icon(copy.icon, size: 40, color: copy.tint),
        ),
        const SizedBox(height: 24),
        Padding(
          padding: const EdgeInsets.symmetric(horizontal: 24),
          child: Text(
            copy.title,
            textAlign: TextAlign.center,
            style: GoogleFonts.inter(
              fontSize: 20,
              fontWeight: FontWeight.w700,
              color: GoOutsColors.deepNavy,
            ),
          ),
        ),
        const SizedBox(height: 8),
        Padding(
          padding: const EdgeInsets.symmetric(horizontal: 32),
          child: Text(
            copy.body,
            textAlign: TextAlign.center,
            style: GoogleFonts.inter(
              fontSize: 13.5,
              color: GoOutsColors.bodyText,
              height: 1.5,
            ),
          ),
        ),
      ],
    );
  }

  // ── Reference ────────────────────────────────────────────────────────────
  //
  // This used to print `widget.bookingId` raw, under a comment that said:
  //
  //     "The real document id, not a GOS-00000-X pattern invented for the
  //      mockup. This is what support and the host both search on, so a guest
  //      reading it down the phone has to be reading the same string that
  //      exists in Firestore."
  //
  // The reasoning was right and the result was still unusable. The id looks
  // like LorC7MLDic9xjrXKq4t8: twenty mixed case characters that overflowed
  // this card and that nobody can read aloud or write down without error.
  //
  // ⚠ THE CODE IS DERIVED FROM THE ID, NOT RANDOM, so the original concern is
  // fully answered. stayBookingReference() is a pure function, createStayBooking
  // writes the same value onto the document with the same algorithm, and
  // support can go either way: id to code with no lookup, code to booking with
  // one indexed query. Bookings made before the field existed still show the
  // right code, because this derives rather than reads. See stay_reference.dart.
  Widget _buildReferenceCard() {
    return Container(
      margin: const EdgeInsets.symmetric(horizontal: 16),
      padding: const EdgeInsets.all(20),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(12),
      ),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          Text(
            'REFERENCE',
            style: GoogleFonts.inter(
              fontSize: 12,
              fontWeight: FontWeight.w700,
              color: GoOutsColors.bodyText,
              letterSpacing: 0.5,
            ),
          ),
          Flexible(
            child: Text(
              stayBookingReference(widget.bookingId),
              textAlign: TextAlign.right,
              overflow: TextOverflow.ellipsis,
              style: GoogleFonts.inter(
                fontSize: 15,
                fontWeight: FontWeight.w700,
                color: GoOutsColors.primaryBlue,
              ),
            ),
          ),
        ],
      ),
    );
  }

  // ── Trip summary ─────────────────────────────────────────────────────────

  static const List<String> _months = <String>[
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December',
  ];

  static String _shortDate(DateTime d) =>
      '${d.day} ${_months[d.month - 1].substring(0, 3)}';

  Widget _buildTripSummaryCard(StayBooking b) {
    final List<StayPhoto> photos =
        List<StayPhoto>.from(_listing?.photos ?? const <StayPhoto>[])
          ..sort((a, b2) => a.order.compareTo(b2.order));

    return Container(
      margin: const EdgeInsets.symmetric(horizontal: 16),
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(12),
      ),
      child: Row(
        children: [
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                _buildInfoRow(
                  Icons.calendar_today_outlined,
                  '${_shortDate(b.checkIn)} to ${_shortDate(b.checkOut)} · '
                  '${b.nights} ${b.nights == 1 ? 'night' : 'nights'}',
                ),
                const SizedBox(height: 16),
                _buildInfoRow(
                  Icons.location_on_outlined,
                  (_listing?.address.town ?? '').isNotEmpty
                      ? _listing!.address.town
                      : (_listing?.title ?? 'Your stay'),
                ),
                const SizedBox(height: 16),
                _buildInfoRow(
                  Icons.people_outline,
                  _guestSummary(b.guests),
                ),
              ],
            ),
          ),
          if (photos.isNotEmpty) ...[
            const SizedBox(width: 12),
            ClipRRect(
              borderRadius: BorderRadius.circular(8),
              child: Image.network(
                photos.first.url,
                width: 80,
                height: 80,
                fit: BoxFit.cover,
                errorBuilder: (_, __, ___) =>
                    const SizedBox(width: 80, height: 80),
              ),
            ),
          ],
        ],
      ),
    );
  }

  static String _guestSummary(StayGuests g) {
    final List<String> parts = <String>[
      '${g.adults} ${g.adults == 1 ? 'adult' : 'adults'}',
      if (g.children > 0)
        '${g.children} ${g.children == 1 ? 'child' : 'children'}',
      if (g.infants > 0)
        '${g.infants} ${g.infants == 1 ? 'infant' : 'infants'}',
    ];
    return parts.join(', ');
  }

  Widget _buildInfoRow(IconData icon, String text) {
    return Row(
      children: [
        Icon(icon, size: 20, color: GoOutsColors.primaryBlue),
        const SizedBox(width: 12),
        Expanded(
          child: Text(
            text,
            style: GoogleFonts.inter(
              fontSize: 13.5,
              fontWeight: FontWeight.w500,
              color: GoOutsColors.deepNavy,
            ),
          ),
        ),
      ],
    );
  }

  // ── Next steps ───────────────────────────────────────────────────────────

  Widget _buildNextSteps(StayBooking b) {
    final List<({IconData icon, String title})> steps;

    switch (b.status) {
      case BookingStatus.pending:
        steps = const [
          (icon: Icons.schedule, title: 'The host replies within 24 hours'),
          (
            icon: Icons.notifications_outlined,
            title: 'We will let you know as soon as they do'
          ),
          (
            icon: Icons.event_available_outlined,
            title: 'Your dates are held until then'
          ),
        ];
      case BookingStatus.confirmed:
      case BookingStatus.inProgress:
        steps = const [
          (
            icon: Icons.photo_camera_outlined,
            title: 'Take your arrival photographs when you get there'
          ),
          (
            icon: Icons.shield_outlined,
            title: 'They are your evidence if a damage claim is made'
          ),
          (
            icon: Icons.storefront_outlined,
            title: 'Earn cashback at GoOuts partners nearby'
          ),
        ];
      case BookingStatus.declined:
      case BookingStatus.cancelledGuest:
      case BookingStatus.cancelledHost:
      case BookingStatus.completed:
      case BookingStatus.disputed:
        return const SizedBox.shrink();
    }

    return Container(
      margin: const EdgeInsets.symmetric(horizontal: 16),
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(12),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            'What happens next',
            style: GoogleFonts.inter(
              fontSize: 15,
              fontWeight: FontWeight.w700,
              color: GoOutsColors.deepNavy,
            ),
          ),
          const SizedBox(height: 16),
          for (final s in steps) ...[
            _buildNextStepItem(s.icon, s.title),
            if (s != steps.last) const SizedBox(height: 12),
          ],
        ],
      ),
    );
  }

  Widget _buildNextStepItem(IconData icon, String title) {
    return Row(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Container(
          padding: const EdgeInsets.all(8),
          decoration: const BoxDecoration(
            color: GoOutsColors.paleBlueTint,
            shape: BoxShape.circle,
          ),
          child: Icon(icon, size: 18, color: GoOutsColors.primaryBlue),
        ),
        const SizedBox(width: 12),
        Expanded(
          child: Padding(
            padding: const EdgeInsets.only(top: 8),
            child: Text(
              title,
              style: GoogleFonts.inter(
                fontSize: 13.5,
                color: GoOutsColors.bodyText,
                height: 1.35,
              ),
            ),
          ),
        ),
      ],
    );
  }

  // ── Actions ──────────────────────────────────────────────────────────────

